package com.vidyavedika.admin_service.controller; import com.vidyavedika.admin_service.service.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/admin") public class AdminController {private final AdminService s; public AdminController(AdminService s){this.s=s;} @GetMapping("/dashboard") public Object dashboard(){return s.dashboard();} @GetMapping("/audit") public Object audit(){return s.logs();} @PostMapping("/audit") public Object audit(@RequestBody Map<String,Object> r){return s.audit(r.get("actorUserId")==null?null:Long.valueOf(r.get("actorUserId").toString()),String.valueOf(r.getOrDefault("action","UNKNOWN")),String.valueOf(r.getOrDefault("resource","UNKNOWN")),String.valueOf(r.getOrDefault("detail","")));}}
